def get_pings(self) -> list[ServicePing]:
    """
    Return all services that have defined a *ping* and bind them to this
    container.

    Returns:
        A list of services that have registered a ping callable.
    """
    pings: dict[type, RegisteredService] = {}

    # Add pings from the registry.
    for rs in self.registry._services.values():
        if rs.ping is not None:
            pings[rs.svc_type] = rs

    # Add pings from the local registry, shadowing registry pings.
    if self._lazy_local_registry is not None:
        for rs in self._lazy_local_registry._services.values():
            # If a local registration exists, it shadows the registry.
            # If the local one has no ping, it's removed from the pings dict.
            if rs.ping is not None:
                pings[rs.svc_type] = rs
            else:
                pings.pop(rs.svc_type, None)

    return [
        ServicePing(
            rs.name,
            iscoroutinefunction(rs.ping),
            rs.svc_type,
            rs.ping,
            self,
        )
        for rs in pings.values()
    ]

